void nextPermutation(vector<int>& nums) {
    int n = nums.size();
    int i = n - 2;
    while (i >= 0 && nums[i] >= nums[i+1]) i--; // Step1: 找下降点
    if (i >= 0) {
        int j = n - 1;
        while (nums[j] <= nums[i]) j--; // Step2: 找刚好大于nums[i]的元素
        swap(nums[i], nums[j]);
    }
    reverse(nums.begin() + i + 1, nums.end()); // Step3: 反转后缀
}
// 三段法：找下降点→找大于值交换→反转后缀为升序 | i=-1时全反转
